 for name,args in [('status',['status','--short']),('stat',['diff','--stat']),('appjs',['diff','--','app.js'])]:(OUT/f'git-final-{name}.txt').write_bytes(subprocess.check_output(['git',*args],cwd=ROOT))
 apphash=hashlib.sha256((ROOT/'app.js').read_bytes()).hexdigest();gitproof={'app_js_initial_sha256':initial['hashes']['app.js'],'app_js_final_sha256':apphash,'hash_equal':apphash==initial['hashes']['app.js'],'diff_equal':(OUT/'git-before-appjs.txt').read_bytes()==(OUT/'git-final-appjs.txt').read_bytes(),'scope':'gitdirty preexistente; não atribuível integralmente à P4','package_version':pkg['dataset_version']};save(OUT/'git-preservacao.json',gitproof)
